import { EgradxApiError } from '@babulvaibhav/egradx-client'

/*
 * Shared by the EGRADX recipes (shadcn registry items from @babulvaibhav/egradx-ui). Copied into your project like the rest of
 * a recipe: change the wording, the formats or the colours here and every recipe follows.
 */

/** Something to tell the person: wire it to your toasts (`sonner`'s `toast[tone](title, { description })`). */
export type Notify = (message: { tone: 'success' | 'info' | 'warning' | 'error'; title: string; description?: string }) => void

/** Used when a recipe is given no `onNotify`: messages are dropped, the screens still show errors inline. */
export const ignoreNotice: Notify = () => {}

/** Badge colours by meaning, for `<Badge variant="outline" className={tone.success}>`. */
export const tone = {
  success: 'border-emerald-500/30 bg-emerald-500/10 text-emerald-700 dark:text-emerald-400',
  warning: 'border-amber-500/30 bg-amber-500/10 text-amber-700 dark:text-amber-400',
  info: 'border-sky-500/30 bg-sky-500/10 text-sky-700 dark:text-sky-400',
  danger: 'border-destructive/30 bg-destructive/10 text-destructive',
  muted: 'text-muted-foreground',
} as const

const dateTime = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' })
const relative = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' })

export function formatDateTime(iso: string | null | undefined): string {
  return iso ? dateTime.format(new Date(iso)) : '—'
}

/** "3 minutes ago", "in 2 hours". */
export function formatRelative(iso: string | null | undefined): string {
  if (!iso) return '—'
  const seconds = (new Date(iso).getTime() - Date.now()) / 1000
  const units: [Intl.RelativeTimeFormatUnit, number][] = [['year', 31536000], ['month', 2592000], ['day', 86400], ['hour', 3600], ['minute', 60]]
  for (const [unit, size] of units) {
    if (Math.abs(seconds) >= size) return relative.format(Math.round(seconds / size), unit)
  }
  return relative.format(Math.round(seconds), 'second')
}

/** `oim.product_updated` → "Oim product updated". */
export function humanize(value: string | null | undefined): string {
  if (!value) return ''
  const words = value.replace(/[._-]+/g, ' ').trim().toLowerCase()
  return words.charAt(0).toUpperCase() + words.slice(1)
}

export function shortId(id: string): string {
  return id.slice(0, 8)
}

/** A channel id as people read it. Unknown ids, added by configuration, are shown as they are. */
export function channelLabel(id: string): string {
  const labels: Record<string, string> = { email: 'Email', sms: 'SMS', whatsapp: 'WhatsApp', slack: 'Slack', webhook: 'Webhook', log: 'Log' }
  return labels[id] ?? id
}

/** What went wrong, to show the person: the server's message, or a plain one. */
export function errorText(error: unknown): string {
  if (error instanceof EgradxApiError) {
    if (error.code === 'NETWORK_ERROR') return 'The server could not be reached. Check your connection and try again.'
    if (error.code === 'ACCESS_DENIED') return 'You do not have permission to do this.'
    return error.message
  }
  return error instanceof Error ? error.message : 'Something went wrong.'
}

export function errorCode(error: unknown): string | undefined {
  return error instanceof EgradxApiError ? error.code : undefined
}

'use client'

import { useEffect, useState, type ReactNode } from 'react'
import { Inbox, LoaderCircle, RefreshCw, Search, ShieldAlert, TriangleAlert, X } from 'lucide-react'
import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'
import { errorCode, errorText } from './egradx-ui'

/* The small pieces every EGRADX recipe shares: empty and error states, a confirmation, a search box. */

interface StateProps {
  icon?: ReactNode
  title: ReactNode
  description?: ReactNode
  action?: ReactNode
  className?: string
}

export function EmptyState({ icon = <Inbox />, title, description, action, className }: StateProps) {
  return (
    <div className={cn('flex flex-col items-center justify-center gap-3 px-6 py-12 text-center', className)}>
      <div className="bg-muted text-muted-foreground flex size-12 items-center justify-center rounded-full [&_svg]:size-5">{icon}</div>
      <div className="space-y-1">
        <p className="font-medium">{title}</p>
        {description && <p className="text-muted-foreground mx-auto max-w-sm text-sm">{description}</p>}
      </div>
      {action}
    </div>
  )
}

/** A failed load: "not allowed" for a refusal, otherwise what went wrong, with a retry. */
export function ErrorState({ error, onRetry, className }: { error: unknown; onRetry?: () => void; className?: string }) {
  if (errorCode(error) === 'ACCESS_DENIED') {
    return (
      <EmptyState
        className={className}
        icon={<ShieldAlert />}
        title="Access restricted"
        description="Your role does not include this. Ask an administrator if you need it."
      />
    )
  }
  return (
    <EmptyState
      className={className}
      icon={<TriangleAlert className="text-destructive" />}
      title="Couldn't load this"
      description={errorText(error)}
      action={
        onRetry && (
          <Button variant="outline" size="sm" onClick={onRetry}>
            <RefreshCw /> Try again
          </Button>
        )
      }
    />
  )
}

interface ConfirmDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  title: ReactNode
  description?: ReactNode
  confirmLabel?: string
  destructive?: boolean
  pending?: boolean
  onConfirm: () => void
}

/** Asks before something that cannot be undone; stays open until the change is done. */
export function ConfirmDialog({ open, onOpenChange, title, description, confirmLabel = 'Confirm', destructive, pending, onConfirm }: ConfirmDialogProps) {
  return (
    <AlertDialog open={open} onOpenChange={(next) => !pending && onOpenChange(next)}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          {description && <AlertDialogDescription>{description}</AlertDialogDescription>}
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={pending}>Cancel</AlertDialogCancel>
          <Button variant={destructive ? 'destructive' : 'default'} disabled={pending} onClick={onConfirm}>
            {pending && <LoaderCircle className="animate-spin" />}
            {confirmLabel}
          </Button>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

/** A search box that reports what was typed once typing pauses. */
export function SearchBox({ value, onChange, placeholder = 'Search…', className }: { value: string; onChange: (value: string) => void; placeholder?: string; className?: string }) {
  const [draft, setDraft] = useState(value)
  useEffect(() => setDraft(value), [value])
  useEffect(() => {
    if (draft.trim() === value) return
    const timer = setTimeout(() => onChange(draft.trim()), 300)
    return () => clearTimeout(timer)
    // Only typing starts the timer.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draft])
  return (
    <div className={cn('relative w-full sm:w-72', className)}>
      <Search className="text-muted-foreground pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2" />
      <Input value={draft} onChange={(event) => setDraft(event.target.value)} placeholder={placeholder} aria-label={placeholder} className="pr-8 pl-9" />
      {draft && (
        <button
          type="button"
          onClick={() => setDraft('')}
          className="text-muted-foreground hover:text-foreground absolute top-1/2 right-2 -translate-y-1/2 rounded p-0.5"
          aria-label="Clear search"
        >
          <X className="size-3.5" />
        </button>
      )}
    </div>
  )
}

'use client'

import { useEffect, useState, type ReactNode } from 'react'
import { Building2, ChevronRight, LoaderCircle } from 'lucide-react'
import { providerIdentityDetails, retryAfterSeconds, type OrganizationChoice } from '@babulvaibhav/egradx-client'
import { useProviderSignIn, type BeforeNavigate } from '@babulvaibhav/egradx-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { cn } from '@/lib/utils'
import { errorCode, errorText } from '../egradx-ui'

/* What the sign-in, sign-up, callback and sign-in-methods screens share. */

/**
 * What went wrong, in words for the person signing in. `error` is an EgradxApiError, or a code on its own (the
 * callback page's `?error=`). `provider` names the provider, where the message mentions it.
 */
export function authErrorText(error: unknown, provider?: string): string {
  const code = typeof error === 'string' ? error : errorCode(error)
  // IDENTITY_LINK_REQUIRED and AUTH_NO_ACCOUNT say which provider and email.
  const identity = providerIdentityDetails(error)
  provider = identity?.providerName ?? provider
  const by = provider ?? 'this provider'
  switch (code) {
    case 'AUTH_INVALID_CREDENTIALS':
      return 'That email or password is not right.'
    case 'AUTH_TOO_MANY_ATTEMPTS': {
      const seconds = retryAfterSeconds(error)
      return seconds ? `Too many attempts. Try again in ${waitText(seconds)}.` : 'Too many attempts. Wait a little, then try again.'
    }
    case 'EMAIL_CODE_INVALID':
      return 'That code is not right. Check the latest email we sent you.'
    case 'EMAIL_CODE_EXPIRED':
      return 'That code has expired. Ask for a new one.'
    case 'EMAIL_CODE_TOO_MANY_ATTEMPTS':
      return 'Too many wrong codes. Ask for a new one.'
    case 'EMAIL_CODE_RATE_LIMITED':
      return 'A code was sent a moment ago. Wait a minute before asking for another.'
    case 'EMAIL_CODE_UNAVAILABLE':
      return 'Codes by email are not available just now. Try another way.'
    case 'SIGNUP_DISABLED':
      return 'Accounts here are by invitation only. Ask an administrator to invite you.'
    case 'SIGNUP_EMAIL_DOMAIN_NOT_ALLOWED':
      return 'Signing up is not open to addresses at this domain.'
    case 'EMAIL_IN_USE':
      return 'An account already uses this email. Sign in instead.'
    case 'ORGANIZATION_NAME_IN_USE':
      return 'An organization with this name already exists. Choose another name.'
    case 'IDENTITY_LINK_REQUIRED':
      return `An account already uses ${identity?.email ?? 'this email'}. Sign in another way, then link ${by} from your profile.`
    case 'IDENTITY_IN_USE':
      return `That ${provider ?? 'provider'} account is already linked to another account here.`
    case 'AUTH_NO_ACCOUNT':
      return identity?.email
        ? `No account here uses ${identity.email}. Ask an administrator for an invitation.`
        : `No account here uses this ${provider ?? 'provider'} sign-in. Ask an administrator for an invitation.`
    case 'OIDC_EMAIL_NOT_VERIFIED':
      return `${provider ?? 'The provider'} has not verified your email address, so it cannot be used here. Verify it there, or sign in another way.`
    case 'OIDC_CODE_INVALID':
      return 'This sign-in has expired or was already used. Start again.'
    case 'OIDC_CANCELLED':
      return 'Sign-in was cancelled.'
    case 'OIDC_STATE_INVALID':
      return 'The sign-in took too long, or was started in another browser. Start again.'
    case 'OIDC_FAILED':
      return `Signing in with ${by} did not work. Try again, or sign in another way.`
    case 'OIDC_PROVIDER_UNKNOWN':
      return 'That sign-in provider is not set up here.'
    case 'SIGN_IN_METHOD_REQUIRED':
      return 'This is your only way to sign in. Set a password or link another provider first.'
    default:
      return typeof error === 'string' ? 'Signing in did not work. Try again.' : errorText(error)
  }
}

function waitText(seconds: number): string {
  return seconds < 90 ? `${seconds} seconds` : `${Math.ceil(seconds / 60)} minutes`
}

/** The error under a form, announced to screen readers. */
export function FormError({ error, provider, children }: { error: unknown; provider?: string; children?: ReactNode }) {
  if (!error) return null
  return (
    <p className="text-destructive text-sm" role="alert">
      {authErrorText(error, provider)}
      {children}
    </p>
  )
}

/**
 * Draws a link with the application's router (Next's `<Link>`, react-router's `<Link to>`), so moving between the
 * sign-in pages does not reload the page. Default: a plain `<a href>`.
 */
export type LinkRenderer = (link: { href: string; className?: string; children: ReactNode }) => ReactNode

export const defaultRenderLink: LinkRenderer = ({ href, className, children }) => (
  <a href={href} className={className}>
    {children}
  </a>
)

/** Icons by provider id (or `password`, `email-code`), e.g. `{ google: <GoogleMark /> }`. */
export type SignInIcons = Partial<Record<string, ReactNode>>

/**
 * A provider's icon: the application's (`icons[id]`), else a neutral monogram. No provider's logo ships here: their
 * marks are theirs, under their own brand rules; bring the official ones through `icons`.
 */
export function ProviderIcon({ id, name, icons }: { id: string; name: string; icons?: SignInIcons }) {
  const icon = icons?.[id]
  if (icon) return <>{icon}</>
  return (
    <span aria-hidden className="border-current/30 inline-flex size-4 shrink-0 items-center justify-center rounded-full border text-[0.6rem] font-semibold leading-none">
      {name.charAt(0).toUpperCase()}
    </span>
  )
}

export interface ProviderButtonsProps {
  /** The providers, as the sign-in options list them (or `SignInMethod`s, which carry their `label`). */
  providers: { id: string; name: string; label?: string }[]
  /** A path here to land on after the provider. */
  returnTo?: string | null
  /** Button text, when a provider has no `label`. Default "Continue with {name}". */
  label?: (name: string) => string
  /** An invitation to accept: kept for the callback page, which sends it with the code by itself. */
  invitationToken?: string | null
  /** Runs just before the browser leaves; return false to stay. */
  onBeforeNavigate?: BeforeNavigate
  disabled?: boolean
  /** `buttons`: one full-width button each. `compact`: a row of icon buttons, the name in their tooltip. */
  layout?: 'buttons' | 'compact'
  icons?: SignInIcons
  className?: string
  buttonClassName?: string
}

/**
 * A button per provider. Each is a navigation: the browser goes to the server, which redirects to the provider and
 * brings the person back to the callback page (`AuthCallback`).
 */
export function ProviderButtons({
  providers,
  returnTo,
  label = (name) => `Continue with ${name}`,
  invitationToken,
  onBeforeNavigate,
  disabled,
  layout = 'buttons',
  icons,
  className,
  buttonClassName,
}: ProviderButtonsProps) {
  const provider = useProviderSignIn({ returnTo, invitationToken, onBeforeNavigate, disabled })
  if (providers.length === 0) return null
  const compact = layout === 'compact'
  return (
    <div className={cn(compact ? 'flex flex-wrap justify-center gap-2' : 'grid gap-2', className)}>
      {providers.map((p) => {
        const text = p.label ?? label(p.name)
        return (
          <Button
            key={p.id}
            type="button"
            variant="outline"
            size={compact ? 'icon' : 'default'}
            className={cn(!compact && 'w-full', buttonClassName)}
            disabled={disabled || provider.going !== null}
            aria-label={compact ? text : undefined}
            title={compact ? text : undefined}
            onClick={() => void provider.start(p.id)}
          >
            {provider.going === p.id ? <LoaderCircle className="animate-spin" /> : <ProviderIcon id={p.id} name={p.name} icons={icons} />}
            {!compact && text}
          </Button>
        )
      })}
    </div>
  )
}

/** "or", between the provider buttons and a form. */
export function OrDivider({ children = 'or', className }: { children?: ReactNode; className?: string }) {
  return (
    <div className={cn('text-muted-foreground flex items-center gap-3 text-xs uppercase', className)}>
      <span className="bg-border h-px flex-1" />
      {children}
      <span className="bg-border h-px flex-1" />
    </div>
  )
}

/**
 * After ORG_SELECTION_REQUIRED: the person belongs to several organizations and picks one. The caller sends the same
 * credentials (password, code or provider sign-in) again with it.
 */
export function OrganizationPicker({
  organizations,
  pending,
  onPick,
  onCancel,
}: {
  organizations: OrganizationChoice[]
  pending?: boolean
  onPick: (organizationId: string) => void
  onCancel?: () => void
}) {
  const [picked, setPicked] = useState<string | null>(null)
  return (
    <div className="space-y-3">
      <p className="text-muted-foreground text-sm">You belong to more than one organization. Which one do you want to open?</p>
      <ul className="divide-y rounded-md border">
        {organizations.map((organization) => (
          <li key={organization.organizationId}>
            <button
              type="button"
              disabled={pending}
              onClick={() => {
                setPicked(organization.organizationId)
                onPick(organization.organizationId)
              }}
              className="hover:bg-muted/60 flex w-full items-center gap-3 px-3 py-2.5 text-left text-sm disabled:opacity-60"
            >
              <Building2 className="text-muted-foreground size-4 shrink-0" />
              <span className="min-w-0 flex-1">
                <span className="block truncate font-medium">{organization.name}</span>
                {organization.roleName && <span className="text-muted-foreground block text-xs">{organization.roleName}</span>}
              </span>
              {pending && picked === organization.organizationId ? (
                <LoaderCircle className="size-4 animate-spin" />
              ) : (
                <ChevronRight className="text-muted-foreground size-4" />
              )}
            </button>
          </li>
        ))}
      </ul>
      {onCancel && (
        <Button type="button" variant="ghost" size="sm" onClick={onCancel} disabled={pending}>
          Back
        </Button>
      )}
    </div>
  )
}

/** The six-digit code field, with "Resend" enabling itself once `resendAvailableAt` has passed. */
export function CodeField({
  id = 'email-code',
  value,
  onChange,
  resendAvailableAt,
  onResend,
  resending,
  className,
}: {
  id?: string
  value: string
  onChange: (value: string) => void
  /** ISO time, or a time in ms, after which a new code may be asked for. */
  resendAvailableAt?: string | number | null
  onResend?: () => void
  resending?: boolean
  className?: string
}) {
  const [now, setNow] = useState(() => Date.now())
  const at = typeof resendAvailableAt === 'string' ? Date.parse(resendAvailableAt) : (resendAvailableAt ?? 0)
  // Re-renders once a second while waiting, so "Resend" enables itself when it may.
  useEffect(() => {
    if (!onResend || now >= at) return
    const timer = setInterval(() => setNow(Date.now()), 1000)
    return () => clearInterval(timer)
  }, [onResend, now, at])
  const wait = Math.max(0, Math.ceil((at - now) / 1000))
  return (
    <div className={cn('space-y-2', className)}>
      <div className="flex items-center justify-between">
        <Label htmlFor={id}>Code</Label>
        {onResend && (
          <Button type="button" variant="link" size="sm" className="h-auto p-0" disabled={wait > 0 || resending} onClick={onResend}>
            {resending ? 'Sending…' : wait > 0 ? `Resend in ${wait}s` : 'Resend code'}
          </Button>
        )}
      </div>
      <Input
        id={id}
        inputMode="numeric"
        autoComplete="one-time-code"
        autoFocus
        maxLength={6}
        placeholder="123456"
        value={value}
        onChange={(event) => onChange(event.target.value.replace(/\D/g, ''))}
      />
    </div>
  )
}

'use client'

import { useEffect, useState, type FormEvent, type ReactNode } from 'react'
import { KeyRound, LoaderCircle, Mail } from 'lucide-react'
import type { EgradxSession, SignInMethod, SignInMethodChoice } from '@babulvaibhav/egradx-client'
import { useSignInMethodList, type BeforeNavigate, type SignInMethodList, type SignInStep } from '@babulvaibhav/egradx-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Skeleton } from '@/components/ui/skeleton'
import { cn } from '@/lib/utils'
import { ErrorState } from '../egradx-common'
import { CodeField, defaultRenderLink, FormError, OrDivider, OrganizationPicker, ProviderIcon, type LinkRenderer, type SignInIcons } from './auth-shared'

/** Parts to restyle, by slot. */
export interface SignInMethodsClassNames {
  providers?: string
  providerButton?: string
  /** A `list` layout's button for the password or the emailed code, and the buttons switching between them. */
  methodButton?: string
  divider?: string
  form?: string
  input?: string
  submit?: string
}

export interface SignInMethodsPickerProps extends SignInMethodChoice {
  /**
   * - `buttons` (default): a full-width button per provider, then the first form (password or emailed code) with a
   *   button to switch to the other.
   * - `list`: every method as a full-width button in order; the password and the code open their form in place.
   * - `compact`: the providers as a row of icon buttons, then the form.
   */
  layout?: 'buttons' | 'list' | 'compact'
  /** Icons by method id: `{ google: <GoogleMark />, 'email-code': <Mail /> }`. Providers default to a neutral monogram. */
  icons?: SignInIcons
  /** Between the providers and the form. `false` leaves it out. Default "or". */
  dividerText?: ReactNode | false
  /** The email to start with (an invitation's address, a "sign in as" hand-over). */
  defaultEmail?: string
  /** A path here to land on after a provider. */
  returnTo?: string | null
  /** An invitation to accept with a provider: kept for the callback page, which sends it by itself. */
  invitationToken?: string | null
  disabled?: boolean
  /** Runs just before the browser leaves for a provider; return false to stay. */
  onBeforeNavigate?: BeforeNavigate
  /** Signed in with a password or a code: go on, e.g. `router.replace(returnTo ?? '/')`. */
  onSignedIn: (session: EgradxSession) => void
  /** Called when the step changes (`methods`, `code`, `organization`), e.g. to retitle the page. */
  onStepChange?: (step: SignInStep) => void
  /** A "forgot your password?" page, shown with the password form. */
  forgotPasswordHref?: string
  /** Draws links with the application's router. Default: `<a href>`. */
  renderLink?: LinkRenderer
  className?: string
  classNames?: SignInMethodsClassNames
}

/**
 * The sign-in methods, drop-in: the ones the application chooses (`methods`, `order`, `labels`) among those the server
 * enabled, laid out as `buttons`, `list` or `compact`, with the emailed-code step and the organization picker. Built
 * on `useSignInMethodList`; for a design of your own, use that hook directly.
 */
export function SignInMethodsPicker({ methods, order, labels, returnTo, invitationToken, disabled, onBeforeNavigate, onSignedIn, ...view }: SignInMethodsPickerProps) {
  const list = useSignInMethodList({ methods, order, labels, returnTo, invitationToken, disabled, onBeforeNavigate, onSignedIn })
  return <SignInMethodsView list={list} {...view} />
}

export interface SignInMethodsViewProps extends Omit<SignInMethodsPickerProps, keyof SignInMethodChoice | 'returnTo' | 'invitationToken' | 'disabled' | 'onBeforeNavigate' | 'onSignedIn'> {
  /** From `useSignInMethodList`, when the page uses it too (for its title, a sign-up link). */
  list: SignInMethodList
}

/** `SignInMethodsPicker`'s drawing, for a `useSignInMethodList` the page holds itself. */
export function SignInMethodsView({
  list,
  layout = 'buttons',
  icons,
  dividerText = 'or',
  defaultEmail = '',
  onStepChange,
  forgotPasswordHref,
  renderLink = defaultRenderLink,
  className,
  classNames = {},
}: SignInMethodsViewProps) {
  const [email, setEmail] = useState(defaultEmail)
  const [password, setPassword] = useState('')
  const [code, setCode] = useState('')
  /** The form open: the password's or the code's. In `list`, none until one is chosen. */
  const [open, setOpen] = useState<SignInMethod['kind'] | null>(null)

  const { step, error } = list
  useEffect(() => {
    onStepChange?.(step)
    // On the step only.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [step])
  // A used-up code means asking again; the message says so.
  useEffect(() => {
    if (error?.code === 'EMAIL_CODE_EXPIRED' || error?.code === 'EMAIL_CODE_TOO_MANY_ATTEMPTS') setCode('')
  }, [error])

  if (list.loading) {
    return (
      <div className={cn('space-y-3', className)}>
        <Skeleton className="h-9 w-full" />
        <Skeleton className="h-9 w-full" />
        <Skeleton className="h-9 w-full" />
      </div>
    )
  }
  if (!list.options) {
    return <ErrorState error={list.loadError} onRetry={list.reload} />
  }
  if (list.methods.length === 0) {
    return <p className={cn('text-muted-foreground text-sm', className)}>No way to sign in is set up here. Ask an administrator.</p>
  }

  const busy = list.disabled || list.pending !== null
  const switchTo = (kind: SignInMethod['kind'] | null) => {
    list.clearError()
    setOpen(kind)
  }

  if (step.kind === 'organization') {
    return (
      <div className={cn('space-y-3', className)}>
        <OrganizationPicker
          organizations={step.organizations}
          pending={list.pending === 'organization'}
          onPick={(organizationId) => void list.chooseOrganization(organizationId)}
          onCancel={list.back}
        />
        <FormError error={list.error} />
      </div>
    )
  }

  if (step.kind === 'code') {
    const submitCode = (event: FormEvent) => {
      event.preventDefault()
      void list.verifyEmailCode(code)
    }
    return (
      <form className={cn('space-y-4', className, classNames.form)} onSubmit={submitCode}>
        <p className="text-muted-foreground text-sm">If {step.email} has an account here, we sent it a six-digit code. It expires after a few minutes.</p>
        <CodeField
          value={code}
          onChange={setCode}
          resendAvailableAt={step.resendAvailableAt}
          resending={list.pending === 'email-code'}
          onResend={() => void list.resendEmailCode()}
          className={classNames.input}
        />
        <FormError error={list.error} />
        <Button type="submit" className={cn('w-full', classNames.submit)} disabled={code.length !== 6 || busy}>
          {list.pending === 'email-code' && <LoaderCircle className="animate-spin" />} Sign in
        </Button>
        <Button
          type="button"
          variant="ghost"
          className="w-full"
          onClick={() => {
            setCode('')
            list.back()
            setOpen('email-code')
          }}
        >
          Use another email
        </Button>
      </form>
    )
  }

  const forms = list.methods.filter((method) => method.kind !== 'provider')
  const formIcon = (method: SignInMethod) => icons?.[method.id] ?? (method.kind === 'email-code' ? <Mail /> : <KeyRound />)
  const active = layout === 'list' ? forms.find((f) => f.kind === open) : (forms.find((f) => f.kind === open) ?? forms[0])
  const others = forms.filter((f) => f !== active)

  const submitPassword = (event: FormEvent) => {
    event.preventDefault()
    void list.signInWithPassword(email, password)
  }
  const submitEmail = (event: FormEvent) => {
    event.preventDefault()
    void list.requestEmailCode(email)
  }

  const form = active?.kind === 'password' ? (
    <form className={cn('space-y-4', classNames.form)} onSubmit={submitPassword}>
      <div className="space-y-2">
        <Label htmlFor="sign-in-username">Email</Label>
        <Input id="sign-in-username" className={classNames.input} autoComplete="username" required disabled={list.disabled} value={email} onChange={(event) => setEmail(event.target.value)} />
      </div>
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <Label htmlFor="sign-in-password">Password</Label>
          {forgotPasswordHref && renderLink({ href: forgotPasswordHref, className: 'text-muted-foreground text-xs underline-offset-4 hover:underline', children: 'Forgot your password?' })}
        </div>
        <Input id="sign-in-password" className={classNames.input} type="password" autoComplete="current-password" required disabled={list.disabled} value={password} onChange={(event) => setPassword(event.target.value)} />
      </div>
      <FormError error={list.error} />
      <Button type="submit" className={cn('w-full', classNames.submit)} disabled={!email.trim() || !password || busy}>
        {list.pending === 'password' && <LoaderCircle className="animate-spin" />} Sign in
      </Button>
    </form>
  ) : active?.kind === 'email-code' ? (
    <form className={cn('space-y-4', classNames.form)} onSubmit={submitEmail}>
      <div className="space-y-2">
        <Label htmlFor="sign-in-email">Email</Label>
        <Input id="sign-in-email" className={classNames.input} type="email" autoComplete="email" required disabled={list.disabled} value={email} onChange={(event) => setEmail(event.target.value)} />
      </div>
      <FormError error={list.error} />
      <Button type="submit" className={cn('w-full', classNames.submit)} disabled={!email.trim() || busy}>
        {list.pending === 'email-code' ? <LoaderCircle className="animate-spin" /> : formIcon(active)} {active.label}
      </Button>
    </form>
  ) : null

  /** A full-width button for a method: a provider leaves, the password or the code opens its form. */
  const methodButton = (method: SignInMethod) =>
    method.kind === 'provider' ? (
      <Button
        key={method.id}
        type="button"
        variant="outline"
        className={cn('w-full', classNames.providerButton)}
        disabled={busy}
        onClick={() => void list.startProvider(method.id)}
      >
        {list.pending === method.id ? <LoaderCircle className="animate-spin" /> : <ProviderIcon id={method.id} name={method.name} icons={icons} />}
        {method.label}
      </Button>
    ) : (
      <Button key={method.id} type="button" variant="outline" className={cn('w-full', classNames.methodButton)} disabled={list.disabled} onClick={() => switchTo(method.kind)}>
        {formIcon(method)} {method.label}
      </Button>
    )

  if (layout === 'list') {
    return (
      <div className={cn('space-y-4', className)}>
        {active ? (
          <>
            {form}
            <Button type="button" variant="ghost" className="w-full" onClick={() => switchTo(null)}>
              Other ways to sign in
            </Button>
          </>
        ) : (
          <>
            <div className={cn('grid gap-2', classNames.providers)}>{list.methods.map(methodButton)}</div>
            {list.error && <FormError error={list.error} />}
          </>
        )}
      </div>
    )
  }

  const providers = list.providers
  return (
    <div className={cn('space-y-4', className)}>
      {providers.length > 0 && (
        layout === 'compact' ? (
          <div className={cn('flex flex-wrap justify-center gap-2', classNames.providers)}>
            {providers.map((method) => (
              <Button
                key={method.id}
                type="button"
                variant="outline"
                size="icon"
                className={classNames.providerButton}
                disabled={busy}
                aria-label={method.label}
                title={method.label}
                onClick={() => void list.startProvider(method.id)}
              >
                {list.pending === method.id ? <LoaderCircle className="animate-spin" /> : <ProviderIcon id={method.id} name={method.name} icons={icons} />}
              </Button>
            ))}
          </div>
        ) : (
          <div className={cn('grid gap-2', classNames.providers)}>{providers.map(methodButton)}</div>
        )
      )}
      {!form && list.error && <FormError error={list.error} />}
      {providers.length > 0 && form && dividerText !== false && <OrDivider className={classNames.divider}>{dividerText}</OrDivider>}
      {form}
      {others.map((method) => (
        <Button key={method.id} type="button" variant="outline" className={cn('w-full', classNames.methodButton)} disabled={list.disabled} onClick={() => switchTo(method.kind)}>
          {formIcon(method)} {method.label}
        </Button>
      ))}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useSignInMethodList } from '@babulvaibhav/egradx-react'
import { Card, CardContent, CardFooter, CardHeader, CardTitle } from '@/components/ui/card'
import { cn } from '@/lib/utils'
import { defaultRenderLink } from './auth-shared'
import { SignInMethodsView, type SignInMethodsPickerProps } from './sign-in-methods-picker'

interface SignInProps extends Omit<SignInMethodsPickerProps, 'onStepChange'> {
  /** The sign-up page, linked when anyone may sign up (`signup: 'organization'`). */
  signUpHref?: string
  title?: string
  /** The card's classes; `className` styles the methods inside it. */
  cardClassName?: string
}

/**
 * The sign-in page: a card around `SignInMethodsPicker` (the providers, email and password, "email me a code", the
 * organization picker) with a link to sign up when anyone may. Every picker prop works here: `methods`, `order`,
 * `labels`, `layout`, `icons`, `defaultEmail`, `invitationToken`, `onBeforeNavigate`, `renderLink`…
 */
export function SignIn({ signUpHref = '/sign-up', title = 'Sign in', cardClassName, ...props }: SignInProps) {
  const { methods, order, labels, returnTo, invitationToken, disabled, onBeforeNavigate, onSignedIn, ...view } = props
  const list = useSignInMethodList({ methods, order, labels, returnTo, invitationToken, disabled, onBeforeNavigate, onSignedIn })
  const [choosing, setChoosing] = useState(false)
  const renderLink = view.renderLink ?? defaultRenderLink

  return (
    <Card className={cn('w-full max-w-sm', cardClassName)}>
      <CardHeader>
        <CardTitle className="text-xl">{choosing ? 'Choose an organization' : title}</CardTitle>
      </CardHeader>
      <CardContent>
        <SignInMethodsView list={list} {...view} onStepChange={(step) => setChoosing(step.kind === 'organization')} />
      </CardContent>
      {list.signupOpen && !choosing && (
        <CardFooter className="justify-center text-sm">
          <span className="text-muted-foreground">New here?&nbsp;</span>
          {renderLink({ href: signUpHref, className: 'font-medium underline-offset-4 hover:underline', children: 'Create an account' })}
        </CardFooter>
      )}
    </Card>
  )
}
